	EXCLUDING_AGENCY,
	ACTIVATION_DATE,
	TERMINATION_DATE,
	RECORD_STATUS,
	CITY,
	STATE,
	ZIP,
	COUNTRY,
	_INGESTED_AT,
	_SOURCE_RUN_ID,
	_SRC_SHA256,
	INGESTED_AT_CLEAN_TS
) as (
    

-- GENERATED by scripts/gen_landing_date_views.py -- do not hand-edit.
-- Regenerate after any change to reports/recon/date_cast_inventory_*.csv or
-- reports/recon/date_derive_rules_*.csv.
--
-- Clean date/time columns for LIBRARY_RAW.LANDING.FED_SAM_EXCLUSIONS, from the
-- 2026-09-03 warehouse-wide date/time inventory. Every original column
-- passes through untouched via source.*; the clean columns sit beside them.
-- See macros/landing_date_casts.sql for how each is built, and
-- macros/ripple_time.sql for the separate mart-level canonical-clock standard
-- this does not replace.

select
    source.*,
    CASE
        WHEN "_INGESTED_AT" IS NULL THEN NULL
        WHEN LENGTH(TO_VARCHAR(ABS(TRUNC("_INGESTED_AT")))) <= 10 THEN DATEADD('second', TRUNC("_INGESTED_AT"), '1970-01-01'::timestamp_ntz)
        WHEN LENGTH(TO_VARCHAR(ABS(TRUNC("_INGESTED_AT")))) <= 13 THEN DATEADD('millisecond', TRUNC("_INGESTED_AT"), '1970-01-01'::timestamp_ntz)
        WHEN LENGTH(TO_VARCHAR(ABS(TRUNC("_INGESTED_AT")))) <= 16 THEN DATEADD('microsecond', TRUNC("_INGESTED_AT"), '1970-01-01'::timestamp_ntz)
        WHEN LENGTH(TO_VARCHAR(ABS(TRUNC("_INGESTED_AT")))) <= 19 THEN DATEADD('nanosecond', TRUNC("_INGESTED_AT"), '1970-01-01'::timestamp_ntz)
        ELSE NULL
    END as ingested_at_clean_ts
from LIBRARY_RAW.LANDING.FED_SAM_EXCLUSIONS as source
  )
